import { Component, Input, OnChanges, SimpleChanges, inject } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TramiteComentarioService } from '../../../../controllers/tramite-comentario.service';
import { TramiteComentario } from '../../../../models/tramite-comentario';
import { StandarResponse } from '../../../../services/api/api-service.service';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';

@Component({
  selector: 'app-tramite-comentarios',
  standalone: true,
  imports: [CommonModule, FormsModule, DatePipe],
  templateUrl: './tramite-comentarios.component.html',
  styleUrl: './tramite-comentarios.component.css',
})
export class TramiteComentariosComponent implements OnChanges {
  @Input() tramiteId: number | undefined;
  @Input() canDeleteAll = false;

  private tramiteComentarioService = inject(TramiteComentarioService);
  private localStorageService = inject(LocalStorageService);
  private dialogService = inject(VanillaDialogService);

  comentarios: TramiteComentario[] = [];
  nuevoComentario = '';
  loading = true;
  guardando = false;
  borrando: Record<number, boolean> = {};
  usuarioId = this.localStorageService.getUser()?.user.id;

  mensajeVisible = false;
  mensajeAlerta = '';
  alertType: 'success' | 'danger' = 'success';

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['tramiteId'] && this.tramiteId) {
      this.loadComentarios();
    }
  }

  async loadComentarios(): Promise<void> {
    if (!this.tramiteId) {
      this.loading = false;
      return;
    }

    const response: StandarResponse<TramiteComentario[]> = await this.tramiteComentarioService.get({
      conditionals: {
        tramite_id: this.tramiteId,
        deleted_at: null,
      },
      relations: ['usuario'],
      loader: true,
    });

    this.comentarios = (response.data || []).sort((a, b) => {
      const dateA = new Date(a.created_at || 0).getTime();
      const dateB = new Date(b.created_at || 0).getTime();
      return dateA - dateB;

    });

    this.loading = false;
  }

  async guardarComentario(): Promise<void> {
    if (!this.nuevoComentario.trim() || !this.tramiteId) {
      return;
    }

    this.guardando = true;

    const nuevoComentario = await this.tramiteComentarioService.new(
      {
        tramite_id: this.tramiteId,
        comentario: this.nuevoComentario,
        usuario_id: this.usuarioId,
      },
      false
    );

    if (nuevoComentario) {
      this.nuevoComentario = '';
      this.showAlert('Comentario guardado exitosamente', 'success');
      // Recargar todos los comentarios
      await this.loadComentarios();
    } else {
      this.showAlert('Error al guardar el comentario', 'danger');
    }

    this.guardando = false;
  }

  async borrarComentario(comentarioId: number | undefined): Promise<void> {
    if (!comentarioId) return;
    const comentario = this.comentarios.find(c => c.id === comentarioId);

    if (!comentario || !this.canDelete(comentario)) return;

    this.dialogService.show({
      title: 'Eliminar comentario',
      body: '¿Estás seguro que deseas eliminar este comentario?',
      respYes: 'Eliminar',
      respNo: 'Cancelar',
      tipo: 'warning'
    }).subscribe((resultado) => {
      if (resultado?.closedByAgree) {
        this.eliminarComentario(comentarioId);
      }
    });
  }

  private async eliminarComentario(comentarioId: number): Promise<void> {
    this.borrando[comentarioId] = true;

    await this.tramiteComentarioService.delete(comentarioId);

    this.comentarios = this.comentarios.filter(c => c.id !== comentarioId);

    this.borrando[comentarioId] = false;
    this.showAlert('Comentario eliminado', 'success');
  }

  isOwner(comentario: TramiteComentario): boolean {
    return comentario.usuario_id === this.usuarioId;
  }

  showAlert(message: string, type: 'success' | 'danger'): void {
    this.mensajeAlerta = message;
    this.alertType = type;
    this.mensajeVisible = true;

    setTimeout(() => {
      this.mensajeVisible = false;
    }, 3000);
  }

  canDelete(comentario: TramiteComentario): boolean {
    return this.canDeleteAll || this.isOwner(comentario);
  }
}